            { title = 'Bonecraft 40–50', note = '• Bone Knife (cap 41): Wind Crystal + Piece Of Walnut Lumber (Chaupire, Northern San d\'Oria, 4880 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil)\n• Horn (cap 47): Wind Crystal + Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil), Ram Horn (Shih Tayuun, Windurst Woods, 18000 gil)\n• Carapace Mask (cap 45): Earth Crystal + Square Of Dhalmel Leather (Kueh Igunahmori, Southern San d\'Oria, 11650 gil), Crab Shell (Shih Tayuun, Windurst Woods, 11490 gil)\n• Carapace Subligar (cap 48), also needs another craft at 12: Earth Crystal + Square Of Linen Cloth (Kuzah Hpirohpon, Windurst Woods, 15000 gil), Square Of Dhalmel Leather (Kueh Igunahmori, Southern San d\'Oria, 11650 gil), Crab Shell (Shih Tayuun, Windurst Woods, 11490 gil)' },
            { title = 'Bonecraft 50–60', note = '• Blood Stone (cap 57): Wind Crystal + Spool Of Grass Thread (Kuzah Hpirohpon, Windurst Woods, 300 gil), Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil), Vial Of Fiend Blood (Pahya Lolohoiv, Kazham, 635 gil)\n• Scorpion Ring (cap 60): Wind Crystal + Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)\n• Bone Scythe (cap 57), also needs another craft at 19: Wind Crystal + Piece Of Yew Lumber (Chaupire, Northern San d\'Oria, 2200 gil), Square Of Grass Cloth (Kuzah Hpirohpon, Windurst Woods, 1600 gil), Sheep Tooth (Shih Tayuun, Windurst Woods, 1000 gil), 2 × Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil)\n• Beetle Knife (cap 59): Wind Crystal + Piece Of Oak Lumber (Chaupire, Northern San d\'Oria, 31600 gil), Beetle Jaw (Shih Tayuun, Windurst Woods, 3025 gil)' },
            { title = 'Bonecraft 60–70', note = '• Bone Patas (cap 68): Fire Crystal + Crab Shell (Shih Tayuun, Windurst Woods, 11490 gil), 2 × Giant Femur (Shih Tayuun, Windurst Woods, 5075 gil), Loop Of Carbon Fiber (Maymunah, Bastok Mines, 6000 gil)\n• Scorpion Mask (cap 64): Earth Crystal + Square Of Ram Leather (Kueh Igunahmori, Southern San d\'Oria, 18120 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)\n• Beast Horn (cap 69): Wind Crystal + 2 × Ram Horn (Shih Tayuun, Windurst Woods, 18000 gil)\n• Scorpion Subligar (cap 67), also needs another craft at 32: Earth Crystal + Square Of Linen Cloth (Kuzah Hpirohpon, Windurst Woods, 15000 gil), Square Of Ram Leather (Kueh Igunahmori, Southern San d\'Oria, 18120 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil)' },
            { title = 'Bonecraft 70–80', note = '• Tigerfangs (cap 79): Fire Crystal + 2 × Black Tiger Fang (Shih Tayuun, Windurst Woods, 12900 gil), Scorpion Shell (Shih Tayuun, Windurst Woods, 12780 gil), Loop Of Carbon Fiber (Maymunah, Bastok Mines, 6000 gil)\n• Ladybug Earring (cap 75): Wind Crystal + Bonecraft Kit 75\n• Coral Ring (cap 80): Wind Crystal + Bonecraft Kit 80\n• Coral Visor (cap 77): Wind Crystal + Square Of Sheep Leather (Kueh Igunahmori, Southern San d\'Oria, 1000 gil), 2 × Coral Fragment' },
            { title = 'Bonecraft 80–90', note = '• Marid Ring (cap 81): Wind Crystal + 2 × Marid Tusk\n• Hellish Bugle (cap 85): Earth Crystal + Bonecraft Kit 85\n• Wivre Hairpin (cap 85): Wind Crystal + Wivre Maul\n• Behemoth Ring (cap 89): Wind Crystal + 2 × Behemoth Horn' },
            { title = 'Bonecraft 90–100', note = '• Mammoth Tusk (cap 94): Wind Crystal + Giant Frozen Head\n• Carapace Breastplate (cap 95): Earth Crystal + Bonecraft Kit 95\n• Trumpet Ring (cap 96): Wind Crystal + 2 × Trumpet Shell\n• Cerberus Ring (cap 98): Wind Crystal + 2 × Cerberus Claw' },
